        // TODO: Call the parent constructor with name and weight
        if (typeof effect !== 'string' || effect.trim() === '') {
            throw new Error("Potion effect cannot be empty.");
        }
        // TODO: Add input validation for potency. Potency must be a positive number.
        this.effect = effect;
        this.potency = potency;
    }

    use() {
        return `Using ${this.name}! ${this.effect} with potency ${this.potency}.`;
    }
}

