class Item {
    constructor(name, weight) {
        if (typeof name !== 'string' || name.trim() === '') {
            throw new Error("Item name cannot be empty.");
        }
        if (typeof weight !== 'number' || weight < 0) {
            throw new Error("Item weight must be a non-negative number.");
        }
        this.name = name;
        this.weight = weight;
    }

    getDescription() {
        return `Item: ${this.name}, Weight: ${this.weight}kg`;
    }
}

class Potion extends Item {
    constructor(name, weight, effect, potency) {
        super(name, weight);
        if (typeof effect !== 'string' || effect.trim() === '') {
            throw new Error("Potion effect cannot be empty.");
        }
        if (typeof potency !== 'number' || potency <= 0) {
            throw new Error("Potion potency must be a positive number.");
        }
        this.effect = effect;
        this.potency = potency;
    }

    use() {
        return `Using ${this.name}! ${this.effect} with potency ${this.potency}.`;
    }
}

